import{z as l,x as o,o as E,c as s,q as e,j as t,D as A,d as i,s as p,S as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Hyper-NA","description":"","frontmatter":{"title":"Hyper-NA","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hyper-na.md","filePath":"litho/hyper-na.md","lastUpdated":1791413859000}'),h={name:"litho/hyper-na.md"};function N(B,a,d,m,D,_){const r=o("Mermaid");return E(),s("div",null,[a[2]||(a[2]=e('<h1 id="hyper-na" tabindex="-1">Hyper-NA <a class="header-anchor" href="#hyper-na" aria-label="Permalink to &quot;Hyper-NA&quot;">​</a></h1><div class="epigraph"><p>0.55 之后若还要靠抬孔径换单次节距，孔径讨论会进入 Hyper-NA；那是公开展望与可行性研究，不是一张可以下单的量产规格书。</p><footer>—— 对照 ASML / Zeiss 在路线图场合对 0.55 之后孔径的公开讨论</footer></div><p><a href="/litho/euv-double-pattern">上一课</a>把 0.33 上「单次不够」收成 LELE/SADP 或等待 High-NA。缺口是：0.55 自己也会在更后面的节距上不够——那时是 High-NA 双重，还是再抬 NA？ASML 在 imec ITF 一类公开场合把 Hyper-NA 写进路线图展望，口径讨论落在 0.75 量级（亦有 0.85 的研究口吻），时间尺度说到 2030 前后；官方澄清过这是愿景与可行性研究。本课只钉孔径讨论里多出来的物理税，不当作 EXE 的下一款产品手册。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分辨率仍按 \\(\\lambda/\\mathrm{NA}\\)。波长锁在 13.5 nm，再缩单次半节距只能加 NA 或再降 \\(k_1\\)。</p><p><span class="marginnote">NA（数值孔径）翻译成大白话：镜头能接收的光锥有多「胖」。按 \\(\\lambda/\\mathrm{NA}\\) 估个量级：\\(13.5\\,\\mathrm{nm} \\div 0.55 \\approx 24.5\\,\\mathrm{nm}\\)，而 \\(13.5 \\div 0.75 = 18\\,\\mathrm{nm}\\)——孔径只抬 0.2，单次能分辨的节距就再缩约四分之一，这就是厂商盯着孔径不放的原因。</span>High-NA 已经用变形光学才把掩模侧角度从多层膜墙上救回来；再往上，主光线、偏振、焦深、胶厚、场尺寸会同时变本加厉。问题是：在「High-NA 双重」与「Hyper-NA 单次」之间，光学是否还存在一个可镀膜、可扫描、可涂胶的点。</p><p>公开能写的只有量级。van den Brink 等把高于约 0.7 的 NA 说成 2030 前后才更看得见的机会；Zeiss 被描述为开始透镜设计研究。没有公开的场尺寸、wph、镜面张数或量产导入年，可当合同用。缺口因此是机制税，不是规格表。</p><h3 id="不要把路线图当采购项" tabindex="-1">不要把路线图当采购项 <a class="header-anchor" href="#不要把路线图当采购项" aria-label="Permalink to &quot;不要把路线图当采购项&quot;">​</a></h3><p>把 Hyper-NA 写成「0.75 NA、某年、某 wph」会越权。ASML 对媒体的澄清是：可行性研究进行中。本课把 0.75 当作公开讨论过的目标量级，用来算 \\(\\mathrm{NA}^2\\) 税，而不是宣布一台尚未承诺的扫描机。</p><p><span class="marginnote">Hyper-NA 不是 High-NA 的改名。High-NA 专指已在建的 0.55 EXE 平台。把两者混称「更高 NA 的 EUV」，在展望课里会把已出货与未承诺焊在一起。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>展望里的光学逻辑与 EXE 同构，只是数字更狠。掩模侧 NA 随硅片 NA / 倍率涨，变形倍率可能还要再拆，场可能更小，拼接与套刻预算更紧。焦深再按 \\(\\mathrm{NA}^2\\) 掉，<a href="/litho/high-na-resist-budget">胶厚预算</a>要从 0.55 的薄膜再往下，倒塌、吸收与随机三角一起收紧。边缘光线角大到偏振对比崩溃时，偏振器会挡掉光子，产率税与随机税同一方向。</p><p>另一条公开对照是：不抬 NA，而在 0.55 上双重，或继续用 0.33 双重加设计规则。Hyper-NA 只在「单次节距的经济性」赢过这些路径时才值得把蔡司镜子再做一代——那是系统经济，不是本课能算出来的净现值。</p><h3 id="与-0-33-0-55-机队的并存" tabindex="-1">与 0.33 / 0.55 机队的并存 <a class="header-anchor" href="#与-0-33-0-55-机队的并存" aria-label="Permalink to &quot;与 0.33 / 0.55 机队的并存&quot;">​</a></h3><p>即使展望兑现，历史也是多代并存：干式与浸没、NXE 与 EXE。Hyper-NA 若出现，也只会吃最紧的层，而不是替换全部 EUV。讨论应落在「哪一层的单次截止」，而不是「哪一年全球切换」。</p>',15)),(E(),t(n,null,{default:A(()=>[p(r,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20NA%5B%22NA%200.55%20%E2%86%92%200.75%22%5D%20--%3E%20RES%5B%22%E6%88%AA%E6%AD%A2%E9%A2%91%E7%8E%87%E4%B8%8A%E7%A7%BB%20%E8%8A%82%E8%B7%9D%E6%9B%B4%E5%B0%8F%22%5D%0A%20%20NA%20--%3E%20DOF%5B%22DOF%20%E6%8C%89%201%2FNA%C2%B2%20%E7%BA%A6%E7%A0%8D%E5%8D%8A%22%5D%0A%20%20DOF%20--%3E%20THIN%5B%22%E8%83%B6%E8%86%9C%E8%A2%AB%E8%BF%AB%E6%9B%B4%E8%96%84%22%5D%0A%20%20THIN%20--%3E%20RISK%5B%22%E5%80%92%E5%A1%8C%E4%B8%8E%E9%9A%8F%E6%9C%BA%E7%BC%BA%E9%99%B7%E6%9B%B4%E9%99%A9%22%5D%0A%20%20NA%20--%3E%20ANGLE%5B%22%E6%8E%A9%E6%A8%A1%E4%BE%A7%E5%85%89%E7%BA%BF%E8%A7%92%E6%9B%B4%E5%A4%A7%22%5D%0A%20%20ANGLE%20--%3E%20FIELD%5B%22%E5%8F%98%E5%BD%A2%E5%80%8D%E7%8E%87%E5%86%8D%E6%8B%86%20%E5%9C%BA%E6%9B%B4%E5%B0%8F%22%5D%0A%20%20ANGLE%20--%3E%20POL%5B%22%E5%81%8F%E6%8C%AF%E5%AF%B9%E6%AF%94%E4%B8%8B%E9%99%8D%22%5D%0A%20%20POL%20--%3E%20LOSS%5B%22%E5%81%8F%E6%8C%AF%E5%99%A8%E6%8C%A1%E5%85%89%20%E4%BA%A7%E7%8E%87%E7%A8%8E%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p>这张图回答的问题是：把孔径从 0.55 抬到 0.75 时，哪些预算在同一时刻被收紧。分辨率是唯一变好的那一项，其余每一支都是要额外付的税。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NA 提高：截止频率上移，单次 \\(k_1\\) 墙后移。同时 DOF \\(\\propto 1/\\mathrm{NA}^2\\)，膜更薄，光子体积更小，随机悬崖前移。</p><p><span class="marginnote">「焦深按 \\(1/\\mathrm{NA}^2\\) 掉」代入数字：从 0.55 抬到 0.75，\\((0.75/0.55)^2 \\approx 1.86\\)，对焦容差只剩原来的一半多一点。可以想象成相机光圈开到最大时稍微失焦就糊——孔径越大，景深越浅，光刻机对焦系统的每一纳米误差都被放大。</span>矢量效应在更大孔径角上把 TM 对比打掉，可能逼出偏振控制，光源光子更贵。多层膜布拉格峰对角度更挑剔，掩模三维与阴影更重，SMO 与波前校正的负担上升。每一条都是 0.55 已经付过的税的加码，没有新的免费物理。</p><p>电子模糊、二次电子射程不随 NA 变。光学截止再往下走，会撞上胶与二次电子的模糊地板——公开讨论里这被当作「孔径不是无限可抬」的理由之一。那是材料与统计的墙，不是镜子没磨好。</p><p><span class="marginnote">初学者容易以为「孔径想抬就能一直抬」。实际上光斑做得再小，曝光光子打进胶里会激发二次电子，这些电子自己要散射几纳米才停——这条模糊地板由材料决定，不随 NA 移动。当地板卡住时，继续抬孔径只是让光更贵，图样并不会更细。</span></p><p><span class="marginnote">不要用实验室显微镜的 0.75 NA 类比扫描机。EUV 投影是多层反射、真空、扫描同步与全芯片场；显微镜物镜的 NA 数字不能平移成 EXE 的下一档规格。</span></p>',7)),(E(),t(n,null,{default:A(()=>[p(r,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXE%5B%22High-NA%200.55%20%E5%8D%95%E6%AC%A1%22%5D%20--%3E%20NEXT%5B%22%E6%9B%B4%E5%AF%86%E8%8A%82%E8%B7%9D%22%5D%0A%20%20NEXT%20--%3E%20DP%5B%220.55%20%E5%8F%8C%E9%87%8D%22%5D%0A%20%20NEXT%20--%3E%20HYP%5B%22Hyper-NA%20%E5%AD%94%E5%BE%84%E5%B1%95%E6%9C%9B%22%5D%0A%20%20HYP%20--%3E%20TAX%5B%22DOF%20%2F%20%E5%81%8F%E6%8C%AF%20%2F%20%E5%9C%BA%20%2F%20%E9%9A%8F%E6%9C%BA%22%5D%0A%20%20DP%20--%3E%20TAX2%5B%22%E5%A5%97%E5%88%BB%E4%B8%8E%E5%BE%AA%E7%8E%AF%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给出未公开的光学处方，不把 0.75 或 0.85 写成已冻结的产品 NA。时间点是展望，会随可行性研究移动。出口管制与镜子产能对 0.55 已经是瓶颈，下一代只会更稀缺。计算光刻、胶、掩模三维必须先在 EXE 上成熟，否则孔径讨论没有工艺落点。把实验室显微镜或掩模显微镜上的高 NA 演示写成扫描机视野，会把场尺寸与扫描同步两笔账漏掉。</p><p>后课默认：0.55 之后的孔径是展望项；量产决策仍在单次 High-NA、High-NA 双重与设计规则之间做，不以 Hyper-NA 为已交付工具。</p><p>计算光刻课程从下一单元的 OPC 开始，不再把未承诺的孔径当作已冻结的成像合同。</p><p><span class="marginnote">引用路线图时写「公开展望 / 可行性研究」，不要写成「ASML 已公布 Hyper-NA 量产机规格」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Hyper-NA 是 0.55 之后再抬 EUV 孔径的公开展望，讨论量级约 0.75，不是量产规格。</li><li>物理税是更薄焦深、更薄胶、更重偏振与掩模三维，随机三角会更紧。</li><li>替代路径是 High-NA 双重与设计规则，不是只有抬 NA 一条路。</li><li>模糊与二次电子不随 NA 消失，孔径有材料地板。</li><li>出处：ASML / Zeiss 在路线图与 ITF 等场合对 High-NA 之后孔径的公开讨论。</li></ul>',7))])}const T=l(h,[["render",N]]);export{u as __pageData,T as default};
